export declare const clearGuideTheme = "/* \u6E05\u6670\u6307\u5357\uFF1A\u6559\u7A0B\u4E0E\u64CD\u4F5C\u624B\u518C */\n#wemd {\n  max-width: 677px;\n  margin: 0 auto;\n  padding: 18px 24px;\n  color: #263b3a;\n  background-color: transparent;\n  font-family: -apple-system, BlinkMacSystemFont, \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\n  font-size: 16px;\n  line-height: 1.82;\n  letter-spacing: 0.012em;\n  word-break: break-word;\n}\n\n#wemd p {\n  margin: 0 0 21px;\n  color: #263b3a;\n  font-size: 16px;\n  line-height: 1.82;\n  text-align: left;\n  text-wrap: pretty;\n}\n\n#wemd h1,\n#wemd h2,\n#wemd h3,\n#wemd h4,\n#wemd h5,\n#wemd h6 {\n  padding: 0;\n  text-align: left;\n}\n\n#wemd h1 {\n  margin: 24px 0 44px;\n  padding: 0 0 18px;\n  border: none;\n  border-bottom: 8px solid #f0c94d;\n  background: transparent;\n}\n\n#wemd h1 .content {\n  color: #172b29;\n  font-size: 30px;\n  font-weight: 800;\n  line-height: 1.4;\n  text-wrap: balance;\n}\n\n#wemd h2 {\n  margin: 45px 0 23px;\n  padding: 0 0 9px;\n  border: none;\n  border-bottom: 4px solid #172b29;\n  background: transparent;\n}\n\n#wemd h2 .content {\n  color: #172b29;\n  font-family: \"SFMono-Regular\", Consolas, monospace;\n  font-size: 19px;\n  font-weight: 750;\n  text-wrap: balance;\n}\n\n#wemd h3 {\n  margin: 32px 0 16px;\n  padding: 0;\n  border-bottom: 1px dashed #8eb1ad;\n}\n\n#wemd h3 .content {\n  display: inline-block;\n  padding: 0 0 6px;\n  color: #075f58;\n  background: transparent;\n  font-family: \"SFMono-Regular\", Consolas, monospace;\n  font-size: 17px;\n  font-weight: 700;\n  text-wrap: balance;\n}\n\n#wemd h4,\n#wemd h5,\n#wemd h6 {\n  margin: 27px 0 13px;\n  padding-bottom: 6px;\n  border-bottom: 1px dashed #8eb1ad;\n}\n\n#wemd h4 .content,\n#wemd h5 .content,\n#wemd h6 .content {\n  color: #176c65;\n  font-size: 16px;\n  font-weight: 700;\n}\n\n#wemd h1 .prefix,\n#wemd h1 .suffix,\n#wemd h2 .prefix,\n#wemd h2 .suffix,\n#wemd h3 .prefix,\n#wemd h3 .suffix,\n#wemd h4 .prefix,\n#wemd h4 .suffix,\n#wemd h5 .prefix,\n#wemd h5 .suffix,\n#wemd h6 .prefix,\n#wemd h6 .suffix {\n  display: none;\n}\n\n#wemd blockquote {\n  border: none;\n}\n\n#wemd .multiquote-1,\n#wemd .multiquote-2,\n#wemd .multiquote-3 {\n  margin: 28px 0;\n  padding: 18px 20px;\n  border: 2px dashed #172b29;\n  background: #fff7cf;\n}\n\n#wemd .multiquote-1 p,\n#wemd .multiquote-2 p,\n#wemd .multiquote-3 p {\n  margin: 0;\n  color: #31514f;\n  font-size: 15px;\n  line-height: 1.8;\n}\n\n#wemd .multiquote-2,\n#wemd .multiquote-3,\n#wemd .multiquote-1 .multiquote-1 {\n  margin: 12px 0 0;\n  padding: 10px 0 0;\n  border: none;\n  border-top: 1px dashed #8eb1ad;\n  background: transparent;\n}\n\n#wemd ul,\n#wemd ol {\n  margin: 20px 0 27px;\n  padding-left: 25px;\n  color: #087f75;\n}\n\n#wemd li section {\n  margin: 6px 0;\n  color: #263b3a;\n  line-height: 1.76;\n}\n\n#wemd ol > li {\n  margin: 14px 0;\n  color: #087f75;\n  font-family: \"SFMono-Regular\", Consolas, monospace;\n  font-size: 20px;\n  font-weight: 750;\n}\n\n#wemd ol > li > section {\n  padding: 2px 0 12px;\n  border: none;\n  border-bottom: 1px solid #b9d0cd;\n  color: #263b3a;\n  background: transparent;\n  font-family: -apple-system, BlinkMacSystemFont, \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\n  font-size: 16px;\n  font-weight: 400;\n}\n\n#wemd a {\n  color: #06736a;\n  font-weight: 650;\n  text-decoration: underline;\n  text-underline-offset: 0.2em;\n}\n\n#wemd strong {\n  color: #064c47;\n  font-weight: 750;\n}\n\n#wemd mark {\n  padding: 1px 4px;\n  color: #4f3a11;\n  background: #f5dda1;\n}\n\n#wemd hr {\n  height: 1px;\n  margin: 44px 0;\n  border: none;\n  background: #9bbdb9;\n}\n\n#wemd figure {\n  margin: 34px 0 39px;\n  padding: 0;\n  border: 2px solid #172b29;\n  border-radius: 0;\n  background: transparent;\n  break-inside: avoid;\n}\n\n#wemd figure a {\n  border: none;\n}\n\n#wemd img,\n#wemd figure a img {\n  display: block;\n  max-width: 100%;\n  height: auto;\n  margin: 0 auto;\n}\n\n#wemd figcaption {\n  margin-top: 0;\n  padding: 9px 12px;\n  color: #ffffff;\n  background: #172b29;\n  font-size: 12px;\n  line-height: 1.65;\n  text-align: left;\n}\n\n#wemd p code,\n#wemd li code,\n#wemd td code,\n#wemd th code {\n  padding: 2px 6px;\n  border: 1px solid #b9d0cd;\n  color: #075f58;\n  background: #eaf3f2;\n  font-family: \"SFMono-Regular\", Consolas, monospace;\n  font-size: 13px;\n}\n\n#wemd pre {\n  margin: 29px 0;\n  border: 1px solid #183f3c;\n  border-top: 6px solid #23a79b;\n  background: #173330;\n  overflow-x: auto;\n}\n\n#wemd pre code,\n#wemd pre code.hljs {\n  display: block;\n  min-width: max-content;\n  padding: 19px 20px;\n  color: #e8f4f2;\n  background: #173330;\n  font-family: \"SFMono-Regular\", Consolas, monospace;\n  font-size: 13px;\n  line-height: 1.7;\n  white-space: pre;\n}\n\n#wemd pre.custom > .mac-sign {\n  display: block;\n  border-bottom: 1px solid #365c58;\n  background: #173330;\n}\n\n#wemd .table-container {\n  margin: 31px 0;\n  overflow-x: auto;\n}\n\n#wemd table {\n  width: 100%;\n  border-collapse: collapse;\n  border: 2px solid #172b29;\n  color: #263b3a;\n  background: #ffffff;\n  text-align: left;\n}\n\n#wemd table tr th,\n#wemd table tr td {\n  min-width: 88px;\n  padding: 10px;\n  border: 1px solid #b9d0cd;\n  font-size: 14px;\n  line-height: 1.6;\n}\n\n#wemd table tr th {\n  color: #172b29;\n  background: #f0c94d;\n  font-weight: 700;\n}\n\n#wemd table tr:nth-child(2n) {\n  background: #eef6f5;\n}\n\n#wemd .callout {\n  margin: 29px 0;\n  padding: 17px 18px;\n  border: 2px solid #172b29;\n  border-radius: 0;\n  color: #263b3a;\n  background: #ffffff;\n  break-inside: avoid;\n}\n\n#wemd .callout-warning {\n  border-color: #8c6500;\n  background: #fff6df;\n}\n\n#wemd .callout-caution {\n  border-color: #a43c31;\n  background: #fff0ed;\n}\n\n#wemd .callout-title {\n  display: inline-block;\n  margin-bottom: 9px;\n  padding: 2px 7px;\n  color: #ffffff;\n  background: #172b29;\n  font-family: \"SFMono-Regular\", Consolas, monospace;\n  font-size: 13px;\n  font-weight: 750;\n}\n\n#wemd .callout p {\n  margin: 0;\n  font-size: 15px;\n}\n\n#wemd .footnote-word,\n#wemd .footnote-ref {\n  color: #087f75;\n  font-weight: 700;\n}\n\n#wemd .footnotes-sep {\n  margin-top: 47px;\n  padding-top: 16px;\n  border-top: 5px solid #087f75;\n}\n\n#wemd .footnote-item {\n  display: flex;\n  margin-top: 9px;\n}\n\n#wemd .footnote-num {\n  width: 30px;\n  flex-shrink: 0;\n  color: #087f75;\n  font-weight: 700;\n}\n\n#wemd .footnote-item p {\n  margin: 0;\n  color: #58716f;\n  font-size: 13px;\n}\n\n#wemd .block-equation {\n  display: block;\n  margin: 30px 0;\n  padding: 18px 10px;\n  border: 1px solid #b9d0cd;\n  background: #f7faf9;\n  text-align: center;\n  overflow-x: auto;\n}\n\n#wemd .block-equation > svg {\n  max-width: 300% !important;\n}\n\n#wemd .inline-equation > svg {\n  vertical-align: middle;\n}\n\n#wemd pre.mermaid {\n  padding: 20px 10px;\n  border: 1px solid #93b8b4;\n  border-top: 5px solid #087f75;\n  background: #ffffff;\n}\n\n#wemd .task-list-item {\n  display: flex;\n  align-items: flex-start;\n  margin: 9px 0 9px -1.2em;\n  padding: 9px 10px;\n  border: 1px solid #c5d8d6;\n  background: #f7faf9;\n  list-style: none;\n}\n\n#wemd .task-list-item input[type='checkbox'] {\n  margin-top: 7px;\n  margin-right: 8px;\n  accent-color: #087f75;\n  pointer-events: none;\n}\n";
